/// Example 7 of `docs/README.md`.
#[rustfmt::skip]
mod docs_readme_7 {
    use mopenzl::{
        ChunkSize, Chunking, Compressor, DecodeOperation, DecoderStatus, Decompressor, EncoderConfig,
        EncoderStatus, InputSize, Operation,
    };

    fn main() -> Result<(), Box<dyn std::error::Error>> {
        let payload = b"incremental payload ".repeat(5_000);
        let config = EncoderConfig::default().with_chunking(Chunking::Fixed(ChunkSize::MIN));
        let mut encoder = Compressor::new(config)?;
        let expected = encoder.compress(&payload)?;

        // Compress in 4 KiB pieces through a small 1 KiB output buffer.
        let mut session = encoder.start(InputSize::Exact(payload.len() as u64).into());
        let mut frame = Vec::new();
        let mut buffer = [0u8; 1024];
        let mut rest = &payload[..];
        loop {
            let take = rest.len().min(4096);
            let operation = if take == rest.len() {
                Operation::End
            } else {
                Operation::Continue
            };
            let progress = session.process(&rest[..take], &mut buffer, operation)?;
            frame.extend_from_slice(&buffer[..progress.produced]);
            rest = &rest[progress.consumed..];
            if progress.status == EncoderStatus::Finished {
                break;
            }
        }
        assert_eq!(frame, expected);

        // Decompress the same way.
        let mut decoder = Decompressor::default();
        let mut session = decoder.start();
        let mut restored = Vec::new();
        let mut position = 0;
        loop {
            let end = (position + 1000).min(frame.len());
            let operation = if end == frame.len() {
                DecodeOperation::Finish
            } else {
                DecodeOperation::Process
            };
            let progress = session.process(&frame[position..end], &mut buffer, operation)?;
            restored.extend_from_slice(&buffer[..progress.produced]);
            position += progress.consumed;
            if progress.status == DecoderStatus::Finished {
                break;
            }
        }
        assert_eq!(restored, payload);
        Ok(())
    }

    #[test]
    fn runs() {
        main().unwrap();
    }
}

/// Example 1 of `docs/codecs.md`.
#[cfg(feature = "all-codecs")]
#[rustfmt::skip]
mod docs_codecs_1 {
    use mopenzl::graph::params::{divide_by, zstd};
    use mopenzl::graph::{GraphBuilder, LocalParams, StandardGraph, StandardNode};
    use mopenzl::input::{Input, Numbers};
    use mopenzl::{Compressor, Decompressor, EncoderConfig};

    fn main() -> Result<(), Box<dyn std::error::Error>> {
        let mut builder = GraphBuilder::new();
        // divide_by with an explicit divisor of 1000, then zstd at level 19.
        let divide = builder.parameterize_node(
            StandardNode::DivideBy,
            LocalParams::default().with_bytes(divide_by::DIVIDE_BY, 1000u64.to_le_bytes().to_vec()),
        )?;
        let zstd19 = builder.parameterize_node(
            StandardNode::Zstd,
            LocalParams::default().with_int(zstd::COMPRESSION_LEVEL, 19),
        )?;
        let to_bytes = builder.static_graph(zstd19, &[StandardGraph::Store.into()])?;
        let start = builder.pipeline(
            &[divide, StandardNode::ConvertNumToSerialLe.into()],
            to_bytes,
        )?;
        let graph = builder.build(start)?;

        let values: Vec<u8> = (0..4096u32)
            .flat_map(|i| (i * 1000).to_le_bytes())
            .collect();
        let numbers = Numbers::try_from((&values[..], 4))?;
        let mut compressor = Compressor::builder(EncoderConfig::default())
            .with_graph(graph)
            .build()?;
        let frame = compressor.compress_inputs(&[Input::from(numbers)])?;
        let outputs = Decompressor::default().decompress_typed(&frame)?;
        assert_eq!(outputs[0].content(), values);
        Ok(())
    }

    #[test]
    fn runs() {
        main().unwrap();
    }
}

/// Example 1 of `docs/dictionaries.md`.
#[cfg(feature = "zstd")]
#[rustfmt::skip]
mod docs_dictionaries_1 {
    use mopenzl::dict::{Dict, DictBundle, DictCodec};

    fn main() -> Result<(), Box<dyn std::error::Error>> {
        let users = Dict::zstd(&br#"{"user":"alice","plan":"pro"}"#.repeat(8), 3)?;
        let events = Dict::new(DictCodec::ZSTD, b"raw dictionary content".to_vec())?;

        // Order matters: the bundle's ID, and the index frames record, follow it.
        let bundle = DictBundle::try_from(vec![users.clone(), events.clone()])?;
        let reversed = DictBundle::try_from(vec![events, users.clone()])?;
        assert_ne!(bundle.id(), reversed.id());

        // Fat bundles round-trip through bytes.
        let fat = Vec::from(&bundle);
        assert_eq!(DictBundle::try_from(&fat[..])?, bundle);
        assert_eq!(bundle.dicts()[0].id(), users.id());
        println!("bundle {}", bundle.id()); // 64 hexadecimal digits
        Ok(())
    }

    #[test]
    fn runs() {
        main().unwrap();
    }
}

